export function findModelCatalogById(id: string): ModelCatalogRecord | undefined {
  return MODEL_CATALOG_DATABASE.find(item => item.id === id);
}

export function getAllModelCatalogRecords(): ModelCatalogRecord[] {
  return MODEL_CATALOG_DATABASE;
}

export function filterModelCatalogByPredicate(predicate: (item: ModelCatalogRecord) => boolean): ModelCatalogRecord[] {
  return MODEL_CATALOG_DATABASE.filter(predicate);
}

export function countModelCatalogRecords(): number {
  return MODEL_CATALOG_DATABASE.length;
}
